-- ============================================================
-- 052 在线课程学习与考试系统 · 数据库初始化脚本
-- 库名 new_052，MySQL 8 / utf8mb4；可重复执行
-- 29 张表：8 业务 + 21 系统/扩展/预警与讨论
-- ============================================================
DROP DATABASE IF EXISTS `new_052`;
CREATE DATABASE `new_052` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `new_052`;

-- 1. course 课程
CREATE TABLE `course` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `course_no` varchar(32) NOT NULL COMMENT '规则 KC+yyMMdd+4位序号，全局唯一',
  `course_name` varchar(100) NOT NULL COMMENT '2至60字，同一学期同院系不可重名',
  `cover_url` varchar(255) NOT NULL COMMENT '上传后的相对路径，禁止外链',
  `intro` text NOT NULL COMMENT '不少于30字，最多2000字',
  `teacher_id` bigint NOT NULL COMMENT '关联 sys_user.id，必须具有教师角色',
  `term_id` bigint NOT NULL COMMENT '关联 sys_term.id，仅可选未结束学期',
  `credit` decimal(3,1) NOT NULL DEFAULT 2.0 COMMENT '0.5至10.0，步长0.5，后端校验',
  `total_hours` int NOT NULL DEFAULT 32 COMMENT '8至128，须等于章节课时合计',
  `course_type` varchar(20) NOT NULL DEFAULT '必修' COMMENT '必修/选修/公选/重修',
  `capacity` int NOT NULL DEFAULT 60 COMMENT '1至500，已选人数不得超过容量',
  `enroll_count` int NOT NULL DEFAULT 0 COMMENT '选课成功加1、退课减1，不得为负',
  `status` varchar(20) NOT NULL DEFAULT '草稿' COMMENT '草稿/待审核/已发布/已结课/已下架',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_course_no` (`course_no`),
  KEY `idx_term_status` (`term_id`, `status`),
  KEY `idx_teacher_status` (`teacher_id`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='课程';

-- 2. course_chapter 章节课时
CREATE TABLE `course_chapter` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `chapter_no` varchar(32) NOT NULL COMMENT '规则 CJ+课程ID后4位+3位序号，同课程内唯一',
  `course_id` bigint NOT NULL COMMENT '关联 course.id，课程结课后不可新增',
  `parent_id` bigint NOT NULL DEFAULT 0 COMMENT '0表示章，非0表示节，最多两级',
  `chapter_name` varchar(100) NOT NULL COMMENT '同级下不可重名，最多60字',
  `node_type` varchar(20) NOT NULL DEFAULT '视频' COMMENT '视频/文档/测验/讨论，决定学习页展示',
  `resource_url` varchar(255) DEFAULT NULL COMMENT '视频或文档相对路径，测验节点为空',
  `duration_min` int NOT NULL DEFAULT 0 COMMENT '0至300，视频节点必填且大于0',
  `min_finish_rate` decimal(5,2) NOT NULL DEFAULT 90.00 COMMENT '0至100，观看达到该比例记为完成',
  `sort_no` int NOT NULL DEFAULT 1 COMMENT '同课程内连续，重复时按创建时间排序',
  `is_required` tinyint NOT NULL DEFAULT 1 COMMENT '1必修 0选修，必修节点计入完成率',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0隐藏，隐藏后学生端不可见',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chapter_no` (`chapter_no`),
  KEY `idx_course_sort` (`course_id`, `sort_no`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='章节课时';

-- 3. enrollment 选课记录
CREATE TABLE `enrollment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `enroll_no` varchar(32) NOT NULL COMMENT '规则 XK+yyMMdd+6位序号，全局唯一',
  `course_id` bigint NOT NULL COMMENT '关联 course.id，同一课程不可重复选课',
  `student_id` bigint NOT NULL COMMENT '关联 sys_user.id，须为在籍学生',
  `class_id` bigint DEFAULT NULL COMMENT '关联 sys_class.id，公选课可为空',
  `source_type` varchar(20) NOT NULL DEFAULT '自选' COMMENT '自选/教务导入/重修/补选',
  `enroll_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '教务导入时取导入时间',
  `progress_rate` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '0至100，按必修节点完成比例计算',
  `study_minutes` int NOT NULL DEFAULT 0 COMMENT '由心跳上报累加，单日不超过720',
  `last_study_time` datetime DEFAULT NULL COMMENT '心跳上报或交卷时刷新',
  `status` varchar(20) NOT NULL DEFAULT '学习中' COMMENT '学习中/已完成/已退课/已冻结',
  `quit_reason` varchar(200) DEFAULT NULL COMMENT '退课时必填，开课2周后禁止自选退课',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_enroll_no` (`enroll_no`),
  UNIQUE KEY `uk_course_student` (`course_id`, `student_id`),
  KEY `idx_student_status` (`student_id`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='选课记录';

-- 4. lesson_progress 学习进度明细
CREATE TABLE `lesson_progress` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `enrollment_id` bigint NOT NULL COMMENT '关联 enrollment.id',
  `chapter_id` bigint NOT NULL COMMENT '关联 course_chapter.id，同一选课同一章节仅一条',
  `watched_seconds` int NOT NULL DEFAULT 0 COMMENT '0至视频时长×1.2，超出部分丢弃',
  `watch_rate` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '0至100，由已观看秒数除以总秒数',
  `play_times` int NOT NULL DEFAULT 0 COMMENT '每次进入播放页加1，暂停不重复计',
  `first_learn_time` datetime DEFAULT NULL COMMENT '第一次心跳上报时写入',
  `last_heart_time` datetime DEFAULT NULL COMMENT '两次心跳间隔小于15秒的不计分',
  `finish_flag` tinyint NOT NULL DEFAULT 0 COMMENT '观看比例达到最低完成比例时置1',
  `device_type` varchar(20) DEFAULT NULL COMMENT 'PC/手机/平板，按浏览器UA归类',
  `abnormal_flag` tinyint NOT NULL DEFAULT 0 COMMENT '1表示快进或倍速异常，需教师复核',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_enroll_chapter` (`enrollment_id`, `chapter_id`),
  KEY `idx_chapter_finish` (`chapter_id`, `finish_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学习进度明细';

-- 5. exam 考试
CREATE TABLE `exam` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `exam_no` varchar(32) NOT NULL COMMENT '规则 KS+yyMMdd+4位序号，全局唯一',
  `course_id` bigint NOT NULL COMMENT '关联 course.id，仅已发布课程可建考试',
  `exam_name` varchar(100) NOT NULL COMMENT '2至60字，同课程内不可重名',
  `exam_type` varchar(20) NOT NULL DEFAULT '期末' COMMENT '章节测验/期中/期末/补考',
  `start_time` datetime NOT NULL COMMENT '必须早于结束时间',
  `end_time` datetime NOT NULL COMMENT '与开始时间间隔不少于考试时长',
  `duration_min` int NOT NULL DEFAULT 90 COMMENT '10至300分钟',
  `total_score` decimal(5,1) NOT NULL DEFAULT 100.0 COMMENT '10至500，题目分值合计须等于总分',
  `paper_mode` varchar(20) NOT NULL DEFAULT '固定卷' COMMENT '固定卷/随机卷，随机卷按题库规则抽题',
  `attempt_limit` tinyint NOT NULL DEFAULT 1 COMMENT '1至3，补考单独新建考试',
  `cheat_level` varchar(20) NOT NULL DEFAULT '标准' COMMENT '宽松/标准/严格，决定切屏容忍次数',
  `status` varchar(20) NOT NULL DEFAULT '待审核' COMMENT '待审核/待开始/进行中/待批阅/已出分/已归档',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_exam_no` (`exam_no`),
  KEY `idx_course_status` (`course_id`, `status`),
  KEY `idx_start_time` (`start_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='考试';

-- 6. exam_question 考试题目
CREATE TABLE `exam_question` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `question_no` varchar(32) NOT NULL COMMENT '规则 TM+课程ID后4位+4位序号，全局唯一',
  `course_id` bigint NOT NULL COMMENT '关联 course.id，跨课程题目不可复用',
  `chapter_id` bigint DEFAULT NULL COMMENT '关联 course_chapter.id，为空表示综合题',
  `question_type` varchar(20) NOT NULL DEFAULT '单选' COMMENT '单选/多选/判断/填空/简答',
  `stem` text NOT NULL COMMENT '不少于5字，禁止只放图片代替文字',
  `options_json` text DEFAULT NULL COMMENT 'JSON数组，单选多选必填且不少于2项',
  `answer` varchar(500) NOT NULL COMMENT '单选填选项键，多选按键升序逗号分隔',
  `analysis` text DEFAULT NULL COMMENT '简答题必填评分要点',
  `difficulty` tinyint NOT NULL DEFAULT 3 COMMENT '1至5，1最易5最难',
  `score` decimal(5,1) NOT NULL DEFAULT 5.0 COMMENT '0.5至50，同一试卷内合计等于总分',
  `use_count` int NOT NULL DEFAULT 0 COMMENT '被加入试卷时加1',
  `status` varchar(20) NOT NULL DEFAULT '已入库' COMMENT '草稿/待审核/已入库/已停用',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_question_no` (`question_no`),
  KEY `idx_course_chapter` (`course_id`, `chapter_id`),
  KEY `idx_type_status` (`question_type`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='考试题目';

-- 7. exam_record 考试答卷
CREATE TABLE `exam_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `record_no` varchar(32) NOT NULL COMMENT '规则 DJ+yyMMdd+6位序号，全局唯一',
  `exam_id` bigint NOT NULL COMMENT '关联 exam.id',
  `student_id` bigint NOT NULL COMMENT '关联 sys_user.id，必须已选该课程',
  `enrollment_id` bigint NOT NULL COMMENT '关联 enrollment.id，用于校验选课状态',
  `attempt_no` tinyint NOT NULL DEFAULT 1 COMMENT '不超过考试设置的允许次数',
  `start_time` datetime NOT NULL COMMENT '进入答题页时写入',
  `submit_time` datetime DEFAULT NULL COMMENT '自动交卷时写入系统时间',
  `objective_score` decimal(5,1) NOT NULL DEFAULT 0.0 COMMENT '系统自动判分',
  `subjective_score` decimal(5,1) NOT NULL DEFAULT 0.0 COMMENT '教师批阅后回写',
  `total_score` decimal(5,1) NOT NULL DEFAULT 0.0 COMMENT '两项之和，不得超过试卷总分',
  `pass_flag` tinyint NOT NULL DEFAULT 0 COMMENT '总得分达到及格分时置1',
  `status` varchar(20) NOT NULL DEFAULT '答题中' COMMENT '答题中/已提交/待批阅/已批阅/强制交卷/作废',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record_no` (`record_no`),
  KEY `idx_exam_student` (`exam_id`, `student_id`),
  KEY `idx_exam_status` (`exam_id`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='考试答卷';

-- 8. cheat_log 防作弊记录
CREATE TABLE `cheat_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `exam_record_id` bigint NOT NULL COMMENT '关联 exam_record.id',
  `event_type` varchar(30) NOT NULL COMMENT '切屏/退出全屏/多端登录/复制题干/超时未交/长时间无操作',
  `event_time` datetime NOT NULL COMMENT '取前端上报时间，与服务器偏差超5分钟按服务器时间记',
  `duration_sec` int NOT NULL DEFAULT 0 COMMENT '0至3600，切屏事件为离开时长',
  `total_count` int NOT NULL DEFAULT 1 COMMENT '同一答卷同一类型累加，达到上限触发强制交卷',
  `device_info` varchar(200) DEFAULT NULL COMMENT '浏览器与系统版本，脱敏后保存',
  `ip_addr` varchar(64) DEFAULT NULL COMMENT 'IPv4或IPv6，用于多端登录判断',
  `handle_result` varchar(50) NOT NULL DEFAULT '记录' COMMENT '记录/警告/强制交卷/判为作弊',
  `handler_id` bigint DEFAULT NULL COMMENT '人工判定时填写，自动处理为空',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  KEY `idx_record_type` (`exam_record_id`, `event_type`),
  KEY `idx_event_time` (`event_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='防作弊记录';



-- ============================================================
-- 052 在线课程学习与考试系统 · 系统表 / 扩展表 DDL
-- 依赖 gen/ddl_business.sql 的 8 张业务表
-- ============================================================

-- 12. sys_term 学期
CREATE TABLE `sys_term` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `term_code` varchar(20) NOT NULL COMMENT '学期编码，如 2026AUT',
  `term_name` varchar(40) NOT NULL COMMENT '学期名称',
  `start_date` date NOT NULL COMMENT '开学日期',
  `end_date` date NOT NULL COMMENT '结束日期',
  `week_count` int NOT NULL DEFAULT 18 COMMENT '教学周数',
  `status` varchar(20) NOT NULL DEFAULT '进行中' COMMENT '未开始/进行中/已结束',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_term_code` (`term_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学期';

-- 13. sys_class 教学班
CREATE TABLE `sys_class` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `class_no` varchar(32) NOT NULL COMMENT '教学班编号 JXB+6位',
  `class_name` varchar(100) NOT NULL COMMENT '教学班名称',
  `course_id` bigint NOT NULL COMMENT '关联 course.id',
  `teacher_id` bigint NOT NULL COMMENT '任课教师',
  `term_id` bigint NOT NULL COMMENT '所属学期',
  `major` varchar(80) DEFAULT NULL COMMENT '授课对象',
  `student_count` int NOT NULL DEFAULT 0 COMMENT '在班人数',
  `capacity` int NOT NULL DEFAULT 60 COMMENT '容量',
  `schedule` varchar(100) DEFAULT NULL COMMENT '上课安排',
  `status` varchar(20) NOT NULL DEFAULT '待开课' COMMENT '待开课/进行中/已结课',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_class_no` (`class_no`),
  KEY `idx_course_term` (`course_id`, `term_id`),
  KEY `idx_teacher` (`teacher_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='教学班';

-- 14. sys_user 用户
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` varchar(50) NOT NULL COMMENT '登录账号',
  `password` varchar(100) NOT NULL COMMENT 'BCrypt 密码',
  `real_name` varchar(50) NOT NULL COMMENT '真实姓名',
  `user_no` varchar(32) DEFAULT NULL COMMENT '学号/工号',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `email` varchar(80) DEFAULT NULL COMMENT '邮箱',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像相对路径',
  `gender` varchar(10) DEFAULT NULL COMMENT '男/女',
  `dept_id` bigint DEFAULT NULL COMMENT '所属院系ID',
  `dept_name` varchar(60) DEFAULT NULL COMMENT '所属院系',
  `title` varchar(40) DEFAULT NULL COMMENT '职称/年级',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `credit_score` int NOT NULL DEFAULT 100 COMMENT '诚信分',
  `last_login_time` datetime DEFAULT NULL COMMENT '最近登录时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  KEY `idx_user_no` (`user_no`),
  KEY `idx_dept` (`dept_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户';

-- 15. sys_role 角色
CREATE TABLE `sys_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_name` varchar(50) NOT NULL COMMENT '角色名称',
  `role_code` varchar(50) NOT NULL COMMENT '角色编码 ROLE_XXX',
  `data_scope` varchar(20) NOT NULL DEFAULT '本人' COMMENT '本人/本部门/全部',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '说明',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_code` (`role_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色';

-- 16. sys_user_role 用户角色
CREATE TABLE `sys_user_role` (
