  `question_no` varchar(32) NOT NULL COMMENT '题目编号快照',
  `sort_no` int NOT NULL DEFAULT 1 COMMENT '题号',
  `question_type` varchar(20) NOT NULL COMMENT '题型快照',
  `stem` text NOT NULL COMMENT '题干快照',
  `options_json` text COMMENT '选项快照',
  `answer` varchar(500) NOT NULL COMMENT '标准答案快照',
