  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record_question` (`exam_record_id`, `question_id`),
  KEY `idx_record` (`exam_record_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='答题明细';

-- 27. risk_rule 预警规则
CREATE TABLE `risk_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_name` varchar(80) NOT NULL COMMENT '规则名称',
  `rule_version` varchar(20) NOT NULL COMMENT '版本号 v3.2',
  `weight_watch` decimal(5,2) NOT NULL DEFAULT 30.00 COMMENT '观看完成率权重%',
  `weight_submit` decimal(5,2) NOT NULL DEFAULT 20.00 COMMENT '提交及时率权重%',
  `weight_quiz` decimal(5,2) NOT NULL DEFAULT 25.00 COMMENT '测验得分率权重%',
  `weight_login` decimal(5,2) NOT NULL DEFAULT 15.00 COMMENT '登录频次权重%',
  `weight_discuss` decimal(5,2) NOT NULL DEFAULT 10.00 COMMENT '讨论参与权重%',
  `low_line` decimal(5,2) NOT NULL DEFAULT 85.00 COMMENT '低风险下限',
  `focus_line` decimal(5,2) NOT NULL DEFAULT 70.00 COMMENT '关注下限',
  `mid_line` decimal(5,2) NOT NULL DEFAULT 55.00 COMMENT '中风险下限',
  `effect_time` datetime DEFAULT NULL COMMENT '生效时间',
  `status` varchar(20) NOT NULL DEFAULT '生效中' COMMENT '草稿/生效中/已停用',
  `remark` varchar(300) DEFAULT NULL COMMENT '修改原因',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule_version` (`rule_version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='预警规则';

-- 28. risk_snapshot 风险计算快照
CREATE TABLE `risk_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `snapshot_no` varchar(40) NOT NULL COMMENT '快照编号 RISK+yyMMdd+编号',
  `student_id` bigint NOT NULL COMMENT '学生',
  `course_id` bigint NOT NULL COMMENT '课程',
  `enrollment_id` bigint NOT NULL COMMENT '选课记录',
  `rule_id` bigint NOT NULL COMMENT '规则',
  `rule_version` varchar(20) NOT NULL COMMENT '规则版本',
  `raw_watch` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '原始观看完成率%',
  `raw_submit` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '原始提交及时率%',
  `raw_quiz` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '原始测验得分率%',
  `raw_login` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '近14天登录天数',
  `raw_discuss` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '有效讨论次数',
  `score_watch` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '归一化得分',
  `score_submit` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '归一化得分',
  `score_quiz` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '归一化得分',
  `score_login` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '归一化得分',
  `score_discuss` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '归一化得分',
  `risk_score` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '风险分',
  `risk_level` varchar(20) NOT NULL DEFAULT '低风险' COMMENT '低风险/关注/中风险/高风险',
  `gap_text` varchar(300) DEFAULT NULL COMMENT '主要短板',
  `suggestion` varchar(300) DEFAULT NULL COMMENT '建议动作',
  `missing_flag` varchar(100) DEFAULT NULL COMMENT '缺失数据提示',
  `calc_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '计算时间',
  `calc_by` bigint DEFAULT NULL COMMENT '计算人',
  `adopt_flag` tinyint NOT NULL DEFAULT 1 COMMENT '1采纳原结果 0已人工修正',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_snapshot_no` (`snapshot_no`),
  KEY `idx_student_course` (`student_id`, `course_id`),
  KEY `idx_calc_time` (`calc_time`),
  KEY `idx_level` (`risk_level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='风险计算快照';

-- 29. risk_correction 风险人工修正
CREATE TABLE `risk_correction` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `snapshot_id` bigint NOT NULL COMMENT '快照',
  `origin_level` varchar(20) NOT NULL COMMENT '原等级',
  `origin_score` decimal(5,2) NOT NULL COMMENT '原分数',
  `new_level` varchar(20) NOT NULL COMMENT '修正后等级',
  `new_score` decimal(5,2) NOT NULL COMMENT '修正后分数',
  `reason` varchar(300) NOT NULL COMMENT '修正原因，不少于5字',
  `correct_by` bigint NOT NULL COMMENT '修正人',
  `correct_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修正时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_snapshot` (`snapshot_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='风险人工修正留痕';

-- 30. discussion_post 讨论主题
CREATE TABLE `discussion_post` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `post_no` varchar(32) NOT NULL COMMENT '主题编号',
  `course_id` bigint NOT NULL COMMENT '课程',
  `chapter_id` bigint DEFAULT NULL COMMENT '章节',
  `author_id` bigint NOT NULL COMMENT '发帖人',
  `title` varchar(150) NOT NULL COMMENT '标题',
  `content` text NOT NULL COMMENT '内容',
  `is_top` tinyint NOT NULL DEFAULT 0 COMMENT '置顶',
  `is_essence` tinyint NOT NULL DEFAULT 0 COMMENT '精华',
  `is_solved` tinyint NOT NULL DEFAULT 0 COMMENT '已解决',
  `reply_count` int NOT NULL DEFAULT 0 COMMENT '回复数',
  `adopt_reply_id` bigint DEFAULT NULL COMMENT '被采纳回复',
  `status` varchar(20) NOT NULL DEFAULT '正常' COMMENT '正常/已关闭/已隐藏',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发帖时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_post_no` (`post_no`),
  KEY `idx_course` (`course_id`),
  KEY `idx_author` (`author_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='讨论主题';

-- 31. discussion_reply 讨论回复
CREATE TABLE `discussion_reply` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `post_id` bigint NOT NULL COMMENT '主题',
  `author_id` bigint NOT NULL COMMENT '回复人',
  `content` text NOT NULL COMMENT '内容',
  `is_adopted` tinyint NOT NULL DEFAULT 0 COMMENT '被采纳',
  `like_count` int NOT NULL DEFAULT 0 COMMENT '点赞数',
  `status` varchar(20) NOT NULL DEFAULT '正常' COMMENT '正常/已隐藏',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '回复时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_post` (`post_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='讨论回复';

-- 32. lesson_heartbeat 学习心跳（15秒上报，快进异常判定用）
CREATE TABLE `lesson_heartbeat` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `enrollment_id` bigint NOT NULL COMMENT '选课记录',
  `chapter_id` bigint NOT NULL COMMENT '章节',
  `report_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上报时间',
  `delta_sec` int NOT NULL DEFAULT 0 COMMENT '本次上报增量秒',
  `abnormal_flag` tinyint NOT NULL DEFAULT 0 COMMENT '1增量超90秒视为快进',
  `device_type` varchar(20) DEFAULT NULL COMMENT 'PC/手机/平板',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_enroll_chapter` (`enrollment_id`, `chapter_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学习心跳上报';

