INSERT INTO `course` (`id`,`course_no`,`course_name`,`cover_url`,`intro`,`teacher_id`,`term_id`,`credit`,`total_hours`,`course_type`,`capacity`,`enroll_count`,`status`,`create_by`,`create_time`,`update_time`) VALUES
(1,'KC26050101','数据结构与算法','/uploads/seed/course/01.jpg','以线性表、树、图与经典算法为主线，配合在线判题与章节测验，帮助学生建立复杂度分析与算法设计能力。',4,3,4.0,8,'必修',80,0,'已发布',4,'2026-06-09 10:00:00','2026-06-12 10:00:00'),
(2,'KC26050102','操作系统原理','/uploads/seed/course/02.jpg','围绕进程管理、内存管理、文件系统与并发控制展开，实验环节使用真实内核模块观察调度行为。',4,3,4.0,8,'必修',75,0,'已发布',4,'2026-06-13 11:00:00','2026-06-16 11:00:00'),
(3,'KC26050103','计算机网络','/uploads/seed/course/03.jpg','自底向上讲解链路层到应用层协议，结合抓包实验理解 TCP 拥塞控制与 HTTP 缓存机制。',4,3,3.5,8,'必修',90,0,'已发布',4,'2026-06-17 12:00:00','2026-06-20 12:00:00'),
(4,'KC26050104','数据库系统概论','/uploads/seed/course/04.jpg','从关系代数到事务与索引优化，配套 MySQL 实操，最终完成一个小型信息系统的库表设计。',4,3,3.5,8,'必修',85,0,'已发布',4,'2026-06-21 13:00:00','2026-06-24 13:00:00'),
(5,'KC26050105','Java 程序设计','/uploads/seed/course/05.jpg','面向零基础学生的 Java 入门课，涵盖语法、集合、异常与 IO，每章配套编程作业与在线测验。',4,3,3.0,8,'必修',100,0,'已发布',4,'2026-06-25 14:00:00','2026-06-28 14:00:00'),
(6,'KC26050106','Web 前端开发','/uploads/seed/course/06.jpg','HTML/CSS/JavaScript 三件套到 Vue 组件化开发，课程项目为可部署的响应式个人主页。',5,3,3.0,8,'选修',70,0,'已发布',5,'2026-06-29 15:00:00','2026-07-02 15:00:00'),
(7,'KC26050107','Python 数据分析','/uploads/seed/course/07.jpg','使用 NumPy 与 Pandas 完成数据清洗、聚合与可视化，案例取自校园开放数据。',5,3,2.5,8,'选修',90,0,'已发布',5,'2026-07-03 09:00:00','2026-07-06 09:00:00'),
(8,'KC26050108','机器学习导论','/uploads/seed/course/08.jpg','覆盖监督学习、模型评估与特征工程，要求学生独立完成一次完整的建模流程与报告。',5,3,3.5,8,'选修',60,0,'已发布',5,'2026-07-07 10:00:00','2026-07-10 10:00:00'),
(9,'KC26050109','大学英语综合','/uploads/seed/course/09.jpg','以学术阅读与写作为核心，配合每周听力任务与口语打卡，侧重四六级应试能力迁移。',5,3,3.0,8,'公选',120,0,'已发布',5,'2026-07-11 11:00:00','2026-07-14 11:00:00'),
(10,'KC26050110','高等数学（上）','/uploads/seed/course/10.jpg','极限、导数与积分的系统训练，每章设置分层习题，配套错题本与阶段自测。',6,3,5.0,8,'必修',150,0,'已发布',6,'2026-07-15 12:00:00','2026-07-18 12:00:00'),
(11,'KC26050111','线性代数','/uploads/seed/course/01.jpg','矩阵运算、向量空间与特征值分解，强调几何直观与工程应用中的降维思想。',6,3,3.0,8,'必修',130,0,'已发布',6,'2026-07-19 13:00:00','2026-07-22 13:00:00'),
(12,'KC26050112','概率论与数理统计','/uploads/seed/course/02.jpg','从随机变量到参数估计与假设检验，结合 A/B 测试案例讲解统计推断的实际用法。',6,3,3.5,8,'必修',120,0,'已发布',6,'2026-07-23 14:00:00','2026-07-26 14:00:00'),
(13,'KC26050113','软件工程','/uploads/seed/course/03.jpg','覆盖需求分析、架构设计、测试与项目管理，课程以大作业形式完成一次完整的敏捷迭代。',4,3,3.0,8,'必修',80,0,'已发布',4,'2026-07-27 15:00:00','2026-07-30 15:00:00'),
(14,'KC26050114','计算机组成原理','/uploads/seed/course/04.jpg','从逻辑门到流水线，配合 Logisim 实验搭建简易 CPU，理解指令执行的完整路径。',4,2,4.0,8,'必修',70,0,'已结课',4,'2026-07-31 09:00:00','2026-08-03 09:00:00'),
(15,'KC26050115','数字逻辑电路','/uploads/seed/course/05.jpg','组合逻辑与时序逻辑设计方法，实验使用 FPGA 开发板完成计数器与状态机实现。',6,2,3.0,8,'必修',65,0,'已结课',6,'2026-08-04 10:00:00','2026-08-07 10:00:00'),
(16,'KC26050116','信息安全基础','/uploads/seed/course/06.jpg','密码学基础、Web 常见漏洞与防护，课程含靶场攻防演练与安全加固报告。',5,2,2.5,8,'选修',55,0,'已结课',5,'2026-08-08 11:00:00','2026-08-11 11:00:00'),
(17,'KC26050117','人工智能伦理','/uploads/seed/course/07.jpg','讨论算法偏见、隐私保护与自动化决策的责任边界，以案例辩论与短文写作为考核方式。',5,2,2.0,8,'公选',100,0,'已结课',5,'2026-08-12 12:00:00','2026-08-15 12:00:00'),
(18,'KC26050118','移动应用开发','/uploads/seed/course/08.jpg','基于 Flutter 的跨平台开发，从布局到状态管理与本地存储，产出可安装的课程 App。',4,3,3.0,8,'选修',60,0,'待审核',4,'2026-08-16 13:00:00','2026-08-19 13:00:00'),
(19,'KC26050119','云计算与虚拟化','/uploads/seed/course/09.jpg','讲解虚拟化原理、容器编排与云原生部署，实验在本地 Kubernetes 集群完成。',4,3,3.0,8,'选修',50,0,'待审核',4,'2026-08-20 14:00:00','2026-08-23 14:00:00'),
(20,'KC26050120','编译原理','/uploads/seed/course/10.jpg','词法分析、语法分析与中间代码生成，课程设计实现一个简化语言的编译器前端。',6,3,3.5,8,'必修',45,0,'待审核',6,'2026-08-24 15:00:00','2026-08-27 15:00:00'),
(21,'KC26050121','计算机图形学','/uploads/seed/course/01.jpg','光栅化管线、几何变换与着色模型，使用 WebGL 完成一个可交互的三维场景。',5,3,3.0,8,'选修',40,0,'待审核',5,'2026-08-28 09:00:00','2026-08-31 09:00:00'),
(22,'KC26050122','自然语言处理','/uploads/seed/course/02.jpg','文本表示、序列模型与预训练语言模型，配套中文情感分析课程项目。',4,3,3.0,8,'选修',50,0,'草稿',4,'2026-09-01 10:00:00','2026-09-04 10:00:00'),
(23,'KC26050123','嵌入式系统设计','/uploads/seed/course/03.jpg','以 ARM Cortex-M 为平台，讲解外设驱动、实时调度与低功耗设计。',6,3,3.5,8,'必修',45,0,'草稿',6,'2026-09-05 11:00:00','2026-09-08 11:00:00'),
(24,'KC26050124','创新创业基础','/uploads/seed/course/04.jpg','从创意验证到商业计划书撰写，采用工作坊形式，邀请校友创业者分享实战经验。',5,3,1.5,8,'公选',200,0,'草稿',5,'2026-09-09 12:00:00','2026-09-12 12:00:00'),
(25,'KC26050125','大学物理（下）','/uploads/seed/course/05.jpg','电磁学与光学部分，因实验设备检修暂停开课，已选学生统一调整到下学期。',6,2,4.0,8,'必修',110,0,'已下架',6,'2026-09-13 13:00:00','2026-09-16 13:00:00'),
(26,'KC26050126','体育与健康','/uploads/seed/course/06.jpg','体质测试与运动技能训练相结合，线上部分为运动损伤预防与营养知识微课。',5,3,1.0,8,'公选',180,0,'已发布',5,'2026-09-17 14:00:00','2026-09-20 14:00:00');
