INSERT INTO `discussion_post` (`id`,`post_no`,`course_id`,`chapter_id`,`author_id`,`title`,`content`,`is_top`,`is_essence`,`is_solved`,`reply_count`,`adopt_reply_id`,`status`,`create_time`,`update_time`) VALUES
(1,'TZ26050101',1,0,10,'关于红黑树旋转次数的疑问','插入结点后若父结点为红色且叔结点为红色，为什么只做变色不做旋转？教材第 3 章的例子我推了两遍还是对不上。',0,0,0,3,NULL,'正常','2026-07-10 21:10:00','2026-07-11 03:10:00'),
(2,'TZ26050102',2,0,11,'进程调度实验里 CFS 的 vruntime 怎么算','实验指导书给的公式是 vruntime += delta * NICE_0_LOAD / weight，但实际跑出来的值总比手算小，可能是哪一步漏了权重归一化？',0,0,0,4,NULL,'正常','2026-08-24 18:48:00','2026-08-25 00:48:00'),
(3,'TZ26050103',3,0,12,'TCP 拥塞窗口实验的复现问题','用 ns-3 复现课件里的慢启动曲线，第 4 个 RTT 就出现了丢包，但课件上第 7 个才丢，是不是初始 ssthresh 设置不一样？',1,0,1,3,NULL,'正常','2026-09-09 12:52:00','2026-09-09 18:52:00'),
(4,'TZ26050104',4,0,13,'数据库索引失效的几种常见写法','在 where 里对索引列做了函数运算、隐式类型转换、前导通配 like，这三种都会让索引失效，还有别的坑吗？',0,1,0,2,NULL,'正常','2026-10-27 09:58:00','2026-10-27 15:58:00'),
(5,'TZ26050105',5,0,14,'Java 集合遍历时删除元素的正确姿势','用 for-each 删除会抛 ConcurrentModificationException，改成 Iterator.remove 就好了，但 ArrayList 内部是怎么检测到并发修改的？',0,0,0,4,NULL,'正常','2026-08-09 16:51:00','2026-08-09 22:51:00'),
(6,'TZ26050106',6,0,15,'Vue3 组合式函数里怎么优雅地取消请求','组件卸载后接口才返回会报错，目前用 AbortController，但多个请求共用 signal 时取消一个会影响其他请求。',0,0,1,4,NULL,'正常','2026-07-13 13:44:00','2026-07-13 19:44:00'),
(7,'TZ26050107',7,0,16,'Pandas 分组聚合后索引层级太深怎么办','groupby 两层之后想直接取第二层做运算，reset_index 之后列名又变成元组，有什么推荐写法？',0,0,0,2,NULL,'正常','2026-09-17 08:48:00','2026-09-17 14:48:00'),
(8,'TZ26050108',8,0,17,'特征标准化必须在划分训练集之前还是之后','如果先对全量数据标准化再划分，是不是就把测试集的分布信息泄漏进训练了？',1,0,0,4,NULL,'正常','2026-09-20 20:17:00','2026-09-21 02:17:00'),
(9,'TZ26050109',9,0,18,'四六级听力精听的正确打开方式','反复听同一段效果不明显，是不是应该先做题再精听错题部分？求一套可执行的流程。',0,1,1,2,NULL,'正常','2026-08-18 19:17:00','2026-08-19 01:17:00'),
(10,'TZ26050110',10,0,9,'定积分换元后上下限忘记改的后果','换元后如果还用原来的上下限会得到相反数，除了多检查还有没有系统性避免的方法？',0,0,0,4,NULL,'正常','2026-09-28 17:41:00','2026-09-28 23:41:00'),
(11,'TZ26050111',11,0,10,'矩阵相似与合同的判别顺序','判断两个矩阵是否相似，先看特征值再看秩，但遇到不可对角化的情形就卡住了。',0,0,0,2,NULL,'正常','2026-09-06 20:25:00','2026-09-07 02:25:00'),
(12,'TZ26050112',12,0,11,'假设检验里 p 值的通俗解释','老师说 p 值不是"原假设为真的概率"，那它到底该怎么向非统计背景的人解释？',0,0,1,3,NULL,'正常','2026-09-24 11:24:00','2026-09-24 17:24:00'),
(13,'TZ26050113',13,0,12,'敏捷迭代中的需求变更该怎么管','迭代进行到一半产品要加需求，团队每次都妥协，导致燃尽图一直上扬。',0,1,0,2,NULL,'正常','2026-08-07 08:06:00','2026-08-07 14:06:00'),
(14,'TZ26050114',14,0,13,'Logisim 里怎么实现指令流水线冒险检测','数据冒险用转发能解决大部分，但 load-use 冒险必须插入气泡，检测逻辑卡了两天。',0,0,0,3,NULL,'正常','2026-07-09 10:24:00','2026-07-09 16:24:00'),
(15,'TZ26050115',15,0,14,'FPGA 板子烧录后没有反应排查思路','综合和实现都通过了，下载也提示成功，但 LED 不亮，电源和时钟都测过是正常的。',0,0,1,4,NULL,'正常','2026-08-28 20:33:00','2026-08-29 02:33:00'),
(16,'TZ26050116',16,0,15,'XSS 过滤用黑名单为什么不够','把 script 关键字过滤掉之后，用 img onerror 还是能执行，白名单方案落地成本又很高。',0,0,0,3,NULL,'正常','2026-10-14 16:40:00','2026-10-14 22:40:00'),
(17,'TZ26050117',17,0,16,'算法推荐是否需要为用户偏见负责','平台说算法只是放大器，但放大本身是不是也构成一种价值选择？想听听不同立场。',0,0,0,4,NULL,'正常','2026-07-19 12:51:00','2026-07-19 18:51:00'),
(18,'TZ26050118',18,0,17,'Flutter 状态管理选 Provider 还是 Riverpod','小项目用 setState 就够，但页面一多就乱，想一次选对避免重构。',0,0,1,2,NULL,'正常','2026-09-07 09:12:00','2026-09-07 15:12:00');
