(3,'关于成绩复核申请流程的调整','成绩发布后 5 天内可在成绩单页提交复核申请，复核由非原阅卷人处理，逾期不再受理。','成绩','2026-06-25 14:00:00',2,'已发布','2026-06-25 14:00:00'),
(4,'学习预警干预功能上线','教师可对中风险以上学生发送学习计划，干预记录同步抄送辅导员。','系统','2026-09-12 11:00:00',1,'已发布','2026-09-12 11:00:00'),
